CREATE OR REPLACE FUNCTION public.fn_get_material_order_items(p_order_id uuid)  RETURNS TABLE(id uuid, order_id uuid, material_product_id uuid, offering_id uuid, fulfilment_mode character varying, quantity integer, unit_price numeric, rental_fee numeric, deposit numeric, line_total numeric, loan_duration_days integer, return_due_date timestamp with time zone, status character varying, created_at timestamp with time zone, product_name character varying, product_sku character varying, image_url character varying, category character varying)  LANGUAGE sql  STABLE AS $function$     SELECT          i.id, i.order_id, i.material_product_id, i.offering_id, i.fulfilment_mode,         i.quantity, i.unit_price, i.rental_fee, i.deposit, i.line_total,         i.loan_duration_days, i.return_due_date, i.status, i.created_at,         p.name AS product_name, p.sku AS product_sku, p.image_url, p.category     FROM material_order_items i     JOIN material_products p ON i.material_product_id = p.id     WHERE i.order_id = p_order_id; $function$ ;
